#!/usr/bin/env python3
"""
gen_config_defaults.py - cross-language SSOT generator for SDK config defaults.

Source of truth: include/FlowConfig.h, include/LogConfig.h, src/base/Log.hpp.

Generates:
  1. Kotlin: SlarkConfigDefaults.kt (numeric defaults)
  2. Kotlin: SlarkLogLevel.kt (log level enum + DEFAULT)
  3. C++:    include/ConfigDefaults.h (static_assert mirror guard)

Usage:
  python3 scripts/gen_config_defaults.py [--check]

  --check   only verify generated files match (for CI)
"""

from __future__ import annotations

import argparse
import ast
import operator
import re
import sys
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
ROOT = SCRIPT_DIR.parent

FLOW_HEADER = ROOT / "include" / "FlowConfig.h"
LOG_CONFIG_HEADER = ROOT / "include" / "LogConfig.h"
LOG_HEADER = ROOT / "src" / "base" / "Log.hpp"
KOTLIN_DIR = (
    ROOT / "src" / "platform" / "Android" / "sdk" / "src" / "main" / "java" / "com" / "slark" / "api"
)
CPP_GUARD = ROOT / "include" / "ConfigDefaults.h"

# (Kotlin name, C++ field, Kotlin type, C++ constexpr expression, C++ literal suffix)
MIRROR = [
    ("sourceLowWatermarkSec", "lowWatermarkSec", "Double",
     "SourceWatermarkConfig{}.lowWatermarkSec", ""),
    ("sourceHighWatermarkSec", "highWatermarkSec", "Double",
     "SourceWatermarkConfig{}.highWatermarkSec", ""),
    ("bufferingStartBufferSec", "startBufferSec", "Double",
     "BufferingConfig{}.startBufferSec", ""),
    ("bufferingRebufferEnterSec", "rebufferEnterSec", "Double",
     "BufferingConfig{}.rebufferEnterSec", ""),
    ("bufferingRebufferExitSec", "rebufferExitSec", "Double",
     "BufferingConfig{}.rebufferExitSec", ""),
    ("dnsCacheTtlSec", "cacheTtlSec", "Double", "DnsConfig{}.cacheTtlSec", ""),
    ("progressLogBytes", "progressLogBytes", "Long", "LogConfig{}.progressLogBytes", "ULL"),
    ("maxLogFileSize", "maxLogFileSize", "Long", "LogConfig{}.maxLogFileSize", "ULL"),
    ("maxLogFileCount", "maxLogFileCount", "Int", "LogConfig{}.maxLogFileCount", "U"),
    ("minLogLevelValue", "minLogLevel", "Int", "LogConfig{}.minLogLevel", ""),
]

KOTLIN_HEADER = """\
//
// Copyright (c) 2026 Nevermore-. All rights reserved.
//
// ⚠️ AUTO-GENERATED by scripts/gen_config_defaults.py — DO NOT EDIT MANUALLY
//

package com.slark.api
"""

CPP_GUARD_TEMPLATE = """\
//
// Copyright (c) 2026 Nevermore-. All rights reserved.
//
// ⚠️ AUTO-GENERATED by scripts/gen_config_defaults.py — DO NOT EDIT MANUALLY
//

#pragma once

#include "FlowConfig.h"
#include "Log.hpp"
#include "LogConfig.h"

namespace slark {{

// Mirrors the Kotlin defaults; regenerate after changing any C++ default.
{asserts}
}}  // namespace slark
"""

FIELD_RE = re.compile(
    r"^\s*(?:constexpr\s+)?[A-Za-z_]\w*\s+([A-Za-z_]\w*)\s*=\s*([^;]+);",
    re.MULTILINE,
)
CONSTANT_RE = re.compile(r"constexpr\s+int\s+kMinLogLevelDefault\s*=\s*(\d+)\s*;")
LOG_TYPE_RE = re.compile(r"enum\s+class\s+LogType\s*\{([^}]*)\}", re.MULTILINE)

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}


def eval_arithmetic(node: ast.AST) -> int | float:
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in _BIN_OPS:
        return _BIN_OPS[type(node.op)](eval_arithmetic(node.left), eval_arithmetic(node.right))
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        value = eval_arithmetic(node.operand)
        return value if isinstance(node.op, ast.UAdd) else -value
    raise ValueError(f"unsupported default expression: {ast.dump(node)}")


def parse_value(expr: str, constants: dict[str, int]) -> int | float:
    expr = expr.split("//")[0].strip()
    if expr in constants:
        return constants[expr]
    return eval_arithmetic(ast.parse(expr, mode="eval").body)


def parse_fields(paths: list[Path]) -> dict[str, int | float]:
    fields: dict[str, int | float] = {}
    constants: dict[str, int] = {}
    for path in paths:
        text = path.read_text(encoding="utf-8")
        match = CONSTANT_RE.search(text)
        if match:
            constants["kMinLogLevelDefault"] = int(match.group(1))
        for name, expr in FIELD_RE.findall(text):
            fields[name] = parse_value(expr, constants)
    if "kMinLogLevelDefault" not in constants:
        raise ValueError("kMinLogLevelDefault not found")
    return fields, constants["kMinLogLevelDefault"]


def parse_log_type(text: str) -> list[tuple[str, int]]:
    match = LOG_TYPE_RE.search(text)
    if not match:
        raise ValueError("LogType enum not found")
    body = re.sub(r"//[^\n]*", "", match.group(1))
    result: list[tuple[str, int]] = []
    current = 0
    for entry in body.split(","):
        entry = entry.strip()
        if not entry:
            continue
        if "=" in entry:
            name, raw = entry.split("=", 1)
            name = name.strip()
            current = int(raw.strip())
        else:
            name = entry
        if name:
            result.append((name, current))
            current += 1
    if not result:
        raise ValueError("LogType enum has no values")
    return result


def upper_snake(name: str) -> str:
    return re.sub(r"(?<!^)(?=[A-Z])", "_", name).upper()


def literal(value: int | float, kind: str, suffix: str) -> str:
    if kind == "Double":
        return f"{float(value):.1f}"
    return f"{int(value)}{suffix}"


def generate_kotlin_defaults(fields: dict[str, int | float]) -> str:
    lines = []
    for kotlin_name, cpp_field, kind, _, _ in MIRROR:
        if cpp_field not in fields:
            raise ValueError(f"default field not found: {cpp_field}")
        value = literal(fields[cpp_field], kind, "L" if kind == "Long" else "")
        lines.append(f"    const val {kotlin_name}: {kind} = {value}")
    return (f"{KOTLIN_HEADER}\nobject SlarkConfigDefaults {{\n"
            + "\n".join(lines) + "\n}\n")


def generate_kotlin_log_level(log_type: list[tuple[str, int]], default_value: int) -> str:
    names = {value: upper_snake(name) for name, value in log_type}
    if default_value not in names:
        raise ValueError(f"kMinLogLevelDefault {default_value} has no LogType value")
    entries = ",\n".join(f"    {upper_snake(name)}({value})" for name, value in log_type)
    return (f"{KOTLIN_HEADER}\nenum class SlarkLogLevel(val value: Int) {{\n{entries};\n\n"
            f"    companion object {{\n        val DEFAULT = {names[default_value]}\n    }}\n}}\n")


def generate_cpp_guard(fields: dict[str, int | float],
                       log_type: list[tuple[str, int]],
                       default_value: int) -> str:
    asserts: list[str] = []
    for _, cpp_field, kind, cpp_expr, suffix in MIRROR:
        value = literal(fields[cpp_field], kind, suffix)
        asserts.append(f'static_assert({cpp_expr} == {value}, "regenerate config defaults");')
    asserts.append(f'static_assert(kMinLogLevelDefault == {default_value}, '
                   '"regenerate config defaults");')
    for name, value in log_type:
        asserts.append(f'static_assert(static_cast<int>(LogType::{name}) == {value}, '
                       '"regenerate config defaults");')
    return CPP_GUARD_TEMPLATE.format(asserts="\n".join(asserts))


def write_if_changed(content: str, path: Path) -> bool:
    if path.exists() and path.read_text(encoding="utf-8") == content:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return True


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Generate cross-language config defaults from C++ headers"
    )
    parser.add_argument("--check", action="store_true",
                        help="Only check if generated files are in sync (for CI)")
    args = parser.parse_args()

    try:
        fields, default_value = parse_fields([FLOW_HEADER, LOG_CONFIG_HEADER])
        log_type = parse_log_type(LOG_HEADER.read_text(encoding="utf-8"))
        outputs = {
            KOTLIN_DIR / "SlarkConfigDefaults.kt": generate_kotlin_defaults(fields),
            KOTLIN_DIR / "SlarkLogLevel.kt": generate_kotlin_log_level(log_type, default_value),
            CPP_GUARD: generate_cpp_guard(fields, log_type, default_value),
        }
    except (ValueError, SyntaxError, OSError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1

    all_ok = True
    for path, content in outputs.items():
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                print(f"  ✗ {path} is out of sync with C++ defaults", file=sys.stderr)
                all_ok = False
            else:
                print(f"  ✓ {path} is up to date")
        else:
            status = "written" if write_if_changed(content, path) else "unchanged"
            print(f"  {path}: {status}")

    if args.check:
        if all_ok:
            print("\n✓ All generated config defaults are in sync")
            return 0
        print("\n✗ Some files are out of sync. Run: python3 scripts/gen_config_defaults.py",
              file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
